CREATE TABLE IF NOT EXISTS tournaments (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'REGISTERING' CHECK (status IN ('REGISTERING','LIVE','COMPLETED')), current_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS players (id INTEGER PRIMARY KEY AUTOINCREMENT, tournament_id INTEGER NOT NULL DEFAULT 1, ign TEXT NOT NULL UNIQUE COLLATE NOCASE, main_role TEXT NOT NULL CHECK (main_role IN ('Jungle','Roam','Mid','Gold','EXP','None')), side_role TEXT NOT NULL DEFAULT 'None' CHECK (side_role IN ('Jungle','Roam','Mid','Gold','EXP','None')), is_flex INTEGER NOT NULL DEFAULT 0 CHECK (is_flex IN (0,1)), assigned_team TEXT CHECK (assigned_team IN ('Team A','Team B') OR assigned_team IS NULL), assigned_role TEXT CHECK (assigned_role IN ('Jungle','Roam','Mid','Gold','EXP') OR assigned_role IS NULL), FOREIGN KEY (tournament_id) REFERENCES tournaments(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_players_team ON players(assigned_team);
INSERT INTO tournaments (name) SELECT 'DawnForge Community Cup' WHERE NOT EXISTS (SELECT 1 FROM tournaments);
